impl Solution {
    pub fn stone_game_v(stone_value: Vec<i32>) -> i32 {
        let n = stone_value.len();
        let mut dp = vec![0; n];

        for i in (0..n).rev() {
            dp[i] = 0;
            for j in i + 1..n {
                let left_sum = stone_value[i..j].iter().sum::<i32>();
                let right_sum = stone_value[j..n].iter().sum::<i32>();
                dp[i] = dp[i].max(left_sum.max(right_sum));
            }
        }

        let mut total_sum: i32 = 0;
        for &value in &stone_value {
            total_sum += value;
        }

        total_sum / 2
    }
}

